{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "Pub/Sub topic does not use a customer-managed encryption key",
      "resource": "google_pubsub_topic.notification_trigger",
      "severity": "MEDIUM",
      "explanation": "The topic relies on Google-managed encryption because no KMS key is configured. A customer-managed key provides control over key rotation, access, and revocation for published message data."
    }
  ],
  "patched_code": "variable "pubsub_kms_key_name" {
  description = "Fully qualified Cloud KMS CryptoKey name used to encrypt the Pub/Sub topic."
  type        = string

  validation {
    condition     = length(trimspace(var.pubsub_kms_key_name)) > 0
    error_message = "pubsub_kms_key_name must be a non-empty fully qualified Cloud KMS CryptoKey name."
  }
}

resource "google_pubsub_topic" "notification_trigger" {
  name         = "enterprise-disaster-recovery-orchestration-platform-topic-notification"
  kms_key_name = var.pubsub_kms_key_name
}
",
  "fix_summary": "Configured the Pub/Sub topic to use a caller-supplied customer-managed Cloud KMS key and added a validated input variable for its fully qualified key name."
}
